with filtered as (select id, dept_id, job_title, salary, hire_date, is_remote, level, lower(level) as level_lower from employees where hire_date > '2024-08-01'), scored as (select *, ntile(3) over (partition by dept_id, job_title order by salary desc, id asc) as salary_bucket, ntile(3) over (partition by job_title order by salary asc, id asc) as salary_bucket_2, avg(salary) over (partition by job_title, dept_id order by hire_date asc, id asc rows between 2 preceding and current row) as salary_avg_2, lead(salary, 2) over (partition by level order by hire_date asc, id asc) as next_salary from filtered), joined as (select s.*, p.location from scored s inner join departments p on s.dept_id = p.id), stats as (select case when salary_avg_2 >= 122923 then 'HIGH' else 'LOW' end as salary_avg_2_tier, percentile_approx(next_salary, array(0.25, 0.5, 0.75)) as next_salary_quartiles, percentile_approx(salary_bucket, 0.9) as salary_bucket_p90, max(salary_avg_2) filter (where job_title = 'Designer') as designer_max_salary_avg_2 from joined group by case when salary_avg_2 >= 122923 then 'HIGH' else 'LOW' end) select salary_avg_2_tier, next_salary_quartiles, salary_bucket_p90, designer_max_salary_avg_2 from stats order by salary_bucket_p90 desc, designer_max_salary_avg_2 asc
